const { withAppBuildGradle } = require('expo/config-plugins');

// Expo's generated app/build.gradle signs release builds with the debug
// keystore. Play rejects that, and the comment above it in the template says as
// much, so the fix is expected to be yours.
//
// It cannot be a hand edit: android/ is gitignored and regenerated by every
// prebuild, so the edit would vanish and the next release would quietly be
// debug-signed again. This runs on every prebuild instead.
//
// The four values are read from Gradle properties, which belong in
// ~/.gradle/gradle.properties, outside the repository entirely. That is
// deliberate: a secret that lives outside the working tree cannot be committed
// by a careless git add, which is a stronger guarantee than gitignore.
const SIGNING_CONFIG = `
        release {
            // Set these in ~/.gradle/gradle.properties, never in the repo.
            if (project.hasProperty('OPENHEART_UPLOAD_STORE_FILE')) {
                storeFile file(OPENHEART_UPLOAD_STORE_FILE)
                storePassword OPENHEART_UPLOAD_STORE_PASSWORD
                keyAlias OPENHEART_UPLOAD_KEY_ALIAS
                keyPassword OPENHEART_UPLOAD_KEY_PASSWORD
            }
        }
`;

// Both anchors are exact strings from the template. If Expo changes either, the
// replacement silently does nothing and the app ships signed with a debug key,
// which Play accepts into internal testing and rejects later. So a missing
// anchor throws: a failed prebuild is a far better outcome than a build that
// looks fine and is not.
const SIGNING_ANCHOR = `    signingConfigs {
        debug {`;

const RELEASE_ANCHOR = `            signingConfig signingConfigs.debug
            def enableShrinkResources`;

function addReleaseSigning(gradle) {
  if (!gradle.includes(SIGNING_ANCHOR)) {
    throw new Error(
      'with-release-signing: the signingConfigs block in the Expo template has ' +
        'changed. Update the anchor rather than shipping a debug-signed build.',
    );
  }

  if (!gradle.includes(RELEASE_ANCHOR)) {
    throw new Error(
      'with-release-signing: the release buildType in the Expo template has ' +
        'changed. Update the anchor rather than shipping a debug-signed build.',
    );
  }

  return gradle
    .replace(SIGNING_ANCHOR, `    signingConfigs {${SIGNING_CONFIG}        debug {`)
    .replace(
      RELEASE_ANCHOR,
      `            signingConfig project.hasProperty('OPENHEART_UPLOAD_STORE_FILE')
                ? signingConfigs.release
                : signingConfigs.debug
            def enableShrinkResources`,
    );
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (modConfig) => {
    if (modConfig.modResults.language !== 'groovy') {
      throw new Error('with-release-signing: expected a Groovy build.gradle');
    }

    modConfig.modResults.contents = addReleaseSigning(modConfig.modResults.contents);

    return modConfig;
  });
};

module.exports.addReleaseSigning = addReleaseSigning;
